import {drawAppearancePreview} from './appearance-preview.js?v=utility-usage-trends-1';
import {LANDSCAPE_STYLES,TREE_CHOICES,applyAppearance,landscapePalette} from './city-appearance.js?v=utility-usage-trends-1';
import {copyBuildingSet,applyBuildingSet} from './building-sets.js?v=utility-usage-trends-1';
import {MAP_SIZES} from './city-grid.js?v=utility-usage-trends-1';
import {generateCity,START_FUNDS} from './terrain-generator.js?v=utility-usage-trends-1';
import {recompute,selection} from './engine.js?v=utility-usage-trends-1';
import {planLandscape,LANDSCAPE} from './landscape.js?v=utility-usage-trends-1';
export function showNewCity({dialog,close,start,exportCity,currentCity,renderer}){
 const $=s=>document.querySelector(s),inheritedSet=copyBuildingSet(currentCity||{});
 dialog('Shape your next city',`<p>Preview and sculpt your landscape for free before accepting it. Your current city stays intact until you accept; export it first to keep a copy.</p><div class="new-city-layout"><div class="new-city-settings"><div class="metric-grid"><label>City name<input id="terrainName" maxlength="50" value="New Haven"></label><label>Mayor<input id="terrainMayor" maxlength="50" value="Mayor"></label><label>Starting year<select id="terrainYear">${[1900,1950,2000,2050].map(y=>`<option ${y===1950?'selected':''}>${y}</option>`).join('')}</select></label><label>Map size<select id="terrainSize">${MAP_SIZES.map(size=>`<option value="${size}">${size} × ${size}${size===48?' · Compact':size===256?' · Largest':''}</option>`).join('')}</select></label><label>Difficulty<select id="terrainDifficulty"><option value="easy">Easy · §50,000</option><option value="medium">Medium · §30,000</option><option value="hard">Hard · §10,000</option></select></label></div><label>Starting point<select id="terrainMode"><option value="empty">Generated empty landscape</option><option value="starter">Prepared starter town · §7,500 setup</option></select></label><fieldset><legend>City artwork</legend><label>Landscape colors<select id="terrainAppearance">${Object.entries(LANDSCAPE_STYLES).map(([key,name])=>`<option value="${key}">${name}</option>`).join('')}</select></label><label>Grove artwork<select id="terrainTreeStyle">${Object.entries(TREE_CHOICES).map(([key,name])=>`<option value="${key}">${name}</option>`).join('')}</select></label><canvas id="terrainArtworkPreview" width="540" height="270" style="width:100%;height:auto;max-width:320px" aria-label="Landscape and grove artwork preview"></canvas><button id="terrainArtworkRotate" type="button">Rotate artwork preview</button><label><input id="terrainBuildingSet" type="checkbox" ${currentCity?'':'disabled'}> Use current city’s building set</label><p class="fine">${Object.keys(inheritedSet.buildingDesigns).length} custom models and ${Object.keys(inheritedSet.buildingReplacements).length} style replacements available. These artwork choices preserve terrain sculpting and starting funds. The building set applies to matching current and future buildings.</p></fieldset><fieldset id="terrainOptions"><legend>Landscape profile</legend><label>Center<select id="terrainCenter"><option value="river">River</option><option value="lake">Lake</option><option value="mountain">Mountain</option><option value="dry">Dry land</option></select></label><div class="coast-options">${['north','east','south','west'].map(e=>`<label><input type="checkbox" name="coast" value="${e}" ${e==='west'?'checked':''}> ${e} coast</label>`).join('')}</div>${['mountains','water','trees'].map((k,i)=>`<label>${k}<input id="terrain-${k}" type="range" min="0" max="100" value="${i?35:30}"></label>`).join('')}<label>Map seed<input id="terrainSeed" type="number" min="0" max="4294967295" step="1" value="73"></label><button id="terrainRegenerate">Regenerate landscape</button></fieldset></div><div class="new-city-preview"><div class="actions"><button id="terrainExport">Export current city</button><button id="terrainAccept" class="primary">Accept this terrain</button><button id="terrainCancel">Cancel</button></div><canvas id="terrainPreview" width="288" height="288" aria-label="Top-down terrain preview; drag to sculpt" style="width:100%;max-width:384px;aspect-ratio:1;display:block;margin:16px auto;touch-action:none"></canvas><label>Free sculpting tool<select id="terrainTool">${Object.entries(LANDSCAPE).map(([k,v])=>`<option value="${k}">${v.name}</option>`).join('')}</select></label><p id="terrainSummary" role="status"></p><p class="fine">Larger maps require more memory and simulation time. Water uses the chosen landscape palette, dark green marks woodland, and lighter ground is higher. Grove artwork appears in the isometric city after acceptance. Drag on the preview to sculpt; leveling uses your starting tile. Ponds need elevation zero. Regenerating discards sculpting. Difficulty currently sets starting funds; the year controls technology unlocks.</p></div></div>`);
 let draft,anchor,artworkRotation=renderer?.rotation||0;const canvas=$('#terrainPreview'),ctx=canvas.getContext('2d');
 const options=()=>({appearance:{landscape:$('#terrainAppearance').value,trees:$('#terrainTreeStyle').value},buildingSet:$('#terrainBuildingSet').checked?inheritedSet:undefined,size:Number($('#terrainSize').value),name:$('#terrainName').value.trim()||'New Haven',mayorName:$('#terrainMayor').value.trim()||'Mayor',startYear:Number($('#terrainYear').value),difficulty:$('#terrainDifficulty').value,starter:$('#terrainMode').value==='starter',seed:Number($('#terrainSeed').value),center:$('#terrainCenter').value,coasts:[...document.querySelectorAll('[name="coast"]:checked')].map(e=>e.value),...Object.fromEntries(['mountains','water','trees'].map(k=>[k,Number($('#terrain-'+k).value)]))});
 function draw(){drawAppearancePreview($('#terrainArtworkPreview'),draft.appearance,artworkRotation,renderer);$('#terrainArtworkRotate').textContent='Rotate artwork · '+['North','East','South','West'][artworkRotation];const scale=canvas.width/draft.size,palette=landscapePalette(draft.appearance.landscape);ctx.clearRect(0,0,canvas.width,canvas.height);for(const t of draft.tiles){ctx.fillStyle=t.type?'#d8ded7':t.terrain==='water'?'rgb('+(t.waterKind==='salt'?palette.salt:palette.fresh).join(',')+')':t.nature?'#40764c':`hsl(${palette.hue-t.elevation*3} ${palette.saturation}% ${palette.lightness+t.elevation*2}%)`;ctx.fillRect(t.x*scale,t.y*scale,scale,scale);}$('#terrainSummary').textContent=`${draft.tiles.filter(t=>t.terrain==='land').length} land tiles · highest elevation ${draft.tiles.reduce((highest,t)=>Math.max(highest,t.elevation),0)} · §${draft.funds.toLocaleString()} starting funds · ${LANDSCAPE_STYLES[draft.appearance.landscape]} · ${TREE_CHOICES[draft.appearance.trees]}${$('#terrainBuildingSet').checked?' · Current building set':''}`;}
 function regenerate(){try{draft=generateCity(options());$('#terrainAccept').disabled=false;$('#terrainOptions').disabled=options().starter;$('#terrainTool').disabled=options().starter;draw();}catch(e){$('#terrainSummary').textContent=e.message;$('#terrainAccept').disabled=true;}}
 $('#terrainArtworkRotate').onclick=()=>{artworkRotation=(artworkRotation+1)%4;draw();};
 const artworkChanged=()=>{try{const o=options();applyAppearance(draft,o.appearance);applyBuildingSet(draft,o.buildingSet||{});draw();}catch(e){$('#terrainSummary').textContent=e.message;}};$('#terrainAppearance').onchange=artworkChanged;$('#terrainTreeStyle').onchange=artworkChanged;$('#terrainBuildingSet').onchange=artworkChanged;
 $('#terrainSize').onchange=regenerate;$('#terrainOptions').onchange=regenerate;$('#terrainMode').onchange=regenerate;
 $('#terrainDifficulty').onchange=()=>{draft.funds=START_FUNDS[options().difficulty]-(options().starter?7500:0);draw();};
 $('#terrainRegenerate').onclick=()=>{$('#terrainSeed').value=crypto.getRandomValues(new Uint32Array(1))[0];regenerate();};
 const point=e=>{const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(draft.size-1,Math.floor((e.clientX-r.left)/r.width*draft.size))),y:Math.max(0,Math.min(draft.size-1,Math.floor((e.clientY-r.top)/r.height*draft.size)))};};
 canvas.onpointerdown=e=>{if(options().starter)return;anchor=point(e);canvas.setPointerCapture(e.pointerId);};canvas.onpointercancel=()=>anchor=null;
 canvas.onpointerup=e=>{if(!anchor)return;const tool=$('#terrainTool').value,plan=planLandscape({...draft,funds:Infinity},tool,selection(tool,anchor,point(e),draft.size));anchor=null;if(!plan.ok){$('#terrainSummary').textContent=plan.error;return;}for(const p of plan.points)Object.assign(draft.tiles[p.y*draft.size+p.x],p);recompute(draft);draw();};
 $('#terrainExport').onclick=exportCity;$('#terrainCancel').onclick=close;$('#terrainAccept').onclick=()=>{const o=options();Object.assign(draft,{name:o.name,mayorName:o.mayorName,startYear:o.startYear,difficulty:o.difficulty});recompute(draft);start(draft);close();};regenerate();
}
